// Home — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Home app's origin (see `apps/registry/apps/home.ts`). */
    readonly VITE_HOME_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/home` calls: its `ProxyMethod` table in
// `web/home/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠⚠ READ-ONLY (web-app-suite.md §8 items 2 and 9): the eight `home.*` reads and their push forms —
// `HOME_METHODS` in `lib/gateway/home.ts`, each by its exact name, never a `home.*` prefix. There is no
// Home write to allow: the runtime maps none (`HomePlugin.kt`). `gatewayPermissions.test.ts` pins that
// Home, and only Home, reaches `home.*`.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  'home.devices',
  'home.devices.observe',
  'home.hubStorage',
  'home.hubStorage.observe',
  'home.automations',
  'home.automations.observe',
  'home.activityPage',
  'home.activity.changes',
]

const PROD_ORIGIN = 'https://home.tenshu.app'

export const home: HostedApp = {
  id: 'home',
  order: 50,
  title: 'Home',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_HOME_ORIGIN',
  devPort: 5181,
  origin: () => appOrigin(import.meta.env.VITE_HOME_ORIGIN, PROD_ORIGIN, 5181),
  methods: METHODS,
  routePath: 'home/*',
  sections: ['', 'automations', 'activity'],
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'home',
    label: 'Home',
    description: 'Your devices, automations and activity — view only, end-to-end encrypted.',
    version: '0.1.0',
    launchPath: '/home',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    // Read only: there is no write to list.
    permissions: [
      {
        id: 'home.read',
        label: 'View your home',
        description: 'See your devices and their last synced state, the hub’s storage, your automations and their run history. Read only.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'homeDevice',
        label: 'HomeDeviceService',
        reason: 'Reads your bridged devices and their state. Read only.',
      },
      {
        id: 'hubManagement',
        label: 'HubManagementService',
        reason: 'Reads your hub’s storage status. Read only.',
      },
      {
        id: 'routine',
        label: 'RoutineService',
        reason: 'Reads your automations and their runs. Read only.',
      },
    ],
  },
}

export default home
